from pathlib import Path
import re,html
root=Path(__file__).resolve().parent.parent
info={1:('La propuesta original','Hero animado, programas y diagnóstico interactivo.','Primera exploración'),2:('Una nueva identidad','Portada editorial, nueva estructura, movimiento y modo oscuro.','Rediseño visual'),3:('Una experiencia para participar','Mapa de orientación, metodología aplicada, historias y hoja de trabajo.','Experiencia interactiva')}
versions=sorted([p for p in root.iterdir() if p.is_dir() and re.fullmatch(r'v\d+',p.name) and (p/'index.html').exists()],key=lambda p:int(p.name[1:]))
cards=''
for p in versions:
 n=int(p.name[1:]);title,desc,tag=info.get(n,(f'Propuesta {n}','Explorá esta nueva versión de Feliz de Emprender.','Nueva propuesta'))
 cards+=f'<a class="version" href="{p.name}/"><div class="card-top"><span class="number">V{n:02}</span><span class="tag">{html.escape(tag)}</span></div><h2>{html.escape(title)}</h2><p>{html.escape(desc)}</p><span class="open">Explorar v{n} <span aria-hidden="true">↗</span></span></a>\n'
page='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Elegí una versión · Feliz de Emprender</title><meta name="description" content="Explorá y compará las propuestas de diseño de Feliz de Emprender."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,500&family=Libre+Franklin:wght@400;500;600;700&display=swap" rel="stylesheet"><style>
:root{color-scheme:light dark;--paper:#faf8f2;--ink:#153f49;--soft:#52635f;--line:#d8e2d9;--card:#fff;--mint:#e2eee6}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 'Libre Franklin',Arial,sans-serif}a{color:inherit}.shell{max-width:1200px;margin:auto;padding:30px 36px}.brand{font:italic 36px/1 'Fraunces',Georgia,serif;letter-spacing:-2px}.brand b{font:24px Georgia;color:#b8891f;vertical-align:top}.brand small{display:block;font:12px Arial;letter-spacing:0;margin-top:5px}header{display:flex;justify-content:space-between;align-items:center;padding-bottom:25px;border-bottom:1px solid var(--line)}.review{font-size:11px;color:var(--soft);letter-spacing:.08em;text-transform:uppercase}.intro{padding:65px 0 38px;max-width:720px}.eyebrow{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--soft)}h1{font:500 clamp(38px,5vw,62px)/1.07 'Fraunces',Georgia,serif;letter-spacing:-2px;margin:20px 0}h1 em{font-weight:400}.intro p{color:var(--soft);max-width:560px}.versions{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:22px}.version{display:flex;flex-direction:column;text-decoration:none;padding:28px;background:var(--card);border:1px solid var(--line);border-radius:18px;min-height:330px;transition:transform .25s,box-shadow .25s}.version:nth-child(2){background:var(--mint)}.version:nth-child(3){background:#f7ebd0}.version:hover{transform:translateY(-7px);box-shadow:0 18px 35px #153f4912}.version:focus-visible{outline:3px solid #a0781c;outline-offset:5px}.card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.number{font:44px 'Fraunces',Georgia,serif;letter-spacing:-2px}.tag{font-size:9px;border:1px solid var(--line);border-radius:30px;padding:5px 9px}.version h2{font:500 28px/1.15 'Fraunces',Georgia,serif;letter-spacing:-.5px;margin:35px 0 14px}.version p{font-size:13px;color:var(--soft);margin:0 0 30px}.open{margin-top:auto;display:flex;justify-content:space-between;font-size:12px;font-weight:700}.open span{font-size:23px;line-height:1}footer{display:flex;justify-content:space-between;gap:20px;margin-top:50px;padding:25px 0;border-top:1px solid var(--line);color:var(--soft);font-size:11px}
@media(prefers-color-scheme:dark){:root{--paper:#102126;--ink:#edf5ef;--soft:#c5d3ce;--line:#486260;--card:#20373b;--mint:#23423f}.version:nth-child(3){background:#443b29}.brand b{color:#f4c65d}}
@media(max-width:600px){.shell{padding:24px 22px}.review{max-width:100px;text-align:right;font-size:9px}.intro{padding:40px 0 25px}.version{min-height:280px}.version h2{margin-top:25px}footer{flex-direction:column;gap:5px;margin-top:30px}}
@media(prefers-reduced-motion:reduce){.version{transition:none}.version:hover{transform:none}}
</style></head><body><div class="shell"><header><div class="brand">Feliz<b aria-hidden="true">☀</b><small>de emprender</small></div><span class="review">Espacio de revisión<br>de propuestas</span></header><main><div class="intro"><span class="eyebrow">Una marca. Distintos caminos para contarla.</span><h1>Explorá las propuestas.<br><em>Elegí tu versión.</em></h1><p>Entrá a cada diseño, recorré la experiencia y compará las alternativas. En todas las versiones podés volver a esta pantalla con «Elegir versión».</p></div><nav class="versions" aria-label="Versiones de Feliz de Emprender">'''+cards+'''</nav></main><footer><span>Feliz de Emprender · by B Process</span><span>Un espacio para construir la próxima versión, juntos.</span></footer></div></body></html>'''
(root/'index.html').write_text(page,encoding='utf-8')
print('Selector generado:', ', '.join(p.name for p in versions))
